replicas = [
    {"host": "dc1-db02", "io": "Yes", "sql": "Yes", "lag": 0},
    {"host": "dc2-db01", "io": "Yes", "sql": "Yes", "lag": 42},
    {"host": "dc2-db02", "io": "Yes", "sql": "No", "lag": None, "err": "1062 Duplicate entry"},
]

def check(r, warn=10, crit=60):
    if r["io"] != "Yes" or r["sql"] != "Yes":
        return "CRIT", "복제 멈춤 (" + r.get("err", "원인 확인") + ")"
    if r["lag"] >= crit:
        return "CRIT", f"{r['lag']}초 밀림"
    if r["lag"] >= warn:
        return "WARN", f"{r['lag']}초 밀림"
    return "OK", "정상"

for r in replicas:
    lv, msg = check(r)
    print(f"[{lv}] {r['host']}: {msg}")

# [OK] dc1-db02: 정상
# [WARN] dc2-db01: 42초 밀림
# [CRIT] dc2-db02: 복제 멈춤 (1062 Duplicate entry)
